/* One run, one identity.

   runId is what ties a Slack message, a lock file, a state record and an n8n
   execution to each other. Without it, "the run that failed" is a thing a human
   has to reconstruct from timestamps.

   It is also published into execution.customData, and that is not optional:
   n8n hands an error workflow the FAILING EXECUTION, not our data, so without
   this the Error Handler cannot tell which month crashed or prove which run
   held the lock — and it then refuses to release that lock, correctly but
   unhelpfully. Wrapped in try/catch because customData is not available on
   every n8n build, and a missing convenience must not fail the run. */

const inp = $input.first().json ?? {};

const lastMonth = () => {
  const d = new Date();
  d.setDate(1);
  d.setMonth(d.getMonth() - 1);
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
};

/* Webhook body first (an explicit ask), then the variable (a deliberate
   re-run of an old month), then last month (the scheduled case). */
const body = inp.body ?? inp;
const month = String(body.month || $vars.RBL_MONTH || lastMonth()).trim();
if (!/^[0-9]{4}-[0-9]{2}$/.test(month)) throw new Error('resolved month is not YYYY-MM: ' + JSON.stringify(month));

const dryRun = body.dryRun === true || body.dryRun === 'true' || $vars.RBL_DRY_RUN === 'true';
const runId = new Date().toISOString().replace(/[:.]/g, '-') + '-' + Math.random().toString(36).slice(2, 8);

try {
  $execution.customData.set('month', month);
  $execution.customData.set('runId', runId);
} catch (e) {
  // Older n8n, or customData disabled. The Error Handler falls back to
  // $vars.RBL_MONTH and says which source it used.
}

const dryFlag = dryRun ? ' --dry-run' : '';

return [{
  json: {
    month,
    dryRun,
    runId,
    startedAt: new Date().toISOString(),
    /* Preflight checks what THIS run will actually run — not everything the
       pipeline could ever need. Step 4 adds 03,04 here when the Cohort Loop
       lands. --run-id lets stage 00 recognise the lock we are about to take as
       our own instead of stopping on it. */
    preflightArgs: '--stages 01,02,03,04,05,06,07,08 --run-id ' + runId + dryFlag,
    stageArgs: dryFlag.trim(),
    lockCommand: null, // filled by the next node
  },
}];

/* Build the quoted lock command. Same discipline as the Stage Runner: the
   only place a value reaches a shell is a Code node that quotes every token. */
const inp = $input.first().json ?? {};
const r = $('Resolve month').first().json;
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
const repo = $vars.RBL_REPO;
if (!repo) throw new Error('n8n variable RBL_REPO is not set — see n8n/SETUP_MONTH_PIPELINE.md');

const command = 'cd ' + q(repo)
  + ' && npm run pipeline --silent -- --stage lock --month ' + q(r.month)
  + ' --acquire --run-id ' + q(r.runId)
  + ' --json';

/* Spread the INCOMING item, not just Resolve month: on the release path this
   carries the severity, title and body that Notify is about to send. */
return [{ json: { ...inp, month: r.month, runId: r.runId, dryRun: r.dryRun, startedAt: r.startedAt, command } }];

/* Did we get the lock? Exit 10 means someone else holds a live one — that is
   a stop, not a failure: two runs on one month interleave writes to
   state/<month>.json and a later re-run then skips work that never happened. */
const out = $('Acquire the month lock').first().json;
const r = $('Resolve month').first().json;

/* THE SENTINEL IS THE ONLY RELIABLE EXIT CODE. Measured on n8n 2.35.7: the
   Execute Command node reports `exitCode` only when the command exits 0. On any
   non-zero exit it emits `{ error }` alone — no exitCode, no stdout — so a
   lock.mjs exit 10 ("someone else holds this month", a decision) is
   indistinguishable from a crash. The command is wrapped to always exit 0 and
   print __EXIT__<code> on stdout. */
const stdoutRaw = String(out.stdout ?? '');
const sentinelMatch = [...stdoutRaw.matchAll(/^__EXIT__(\d+)\s*$/gm)].pop();
const exitCode = sentinelMatch ? Number(sentinelMatch[1])
  : (Number.isFinite(Number(out.exitCode)) ? Number(out.exitCode) : (out.error ? 1 : 0));
const stdout = stdoutRaw.replace(/^__EXIT__\d+\s*$/gm, '');
const line = stdout.split('\n').map((l) => l.trim()).filter((l) => l.startsWith('{')).pop();
let res = null;
try { res = line ? JSON.parse(line) : null; } catch (e) { res = null; }

const acquired = exitCode === 0 && res?.acquired === true;

return [{
  json: {
    ...r,
    acquired,
    exitCode,
    lock: res?.lock ?? null,
    /* Taking a stale lock is legitimate but must be visible: it means a
       previous run died without releasing, and that is worth a line in the
       run report rather than silence. */
    tookStale: !!res?.tookFrom,
    lockReason: res?.reason ?? null,
    holder: res?.holder ?? null,
  },
}];

/* Another run holds this month. Do NOT release it — it is not ours, and
   lock.mjs would refuse anyway. Report and stop. */
const j = $input.first().json;
return [{
  json: {
    ...j,
    severity: 'stop',
    stage: 'lock',
    title: 'another run holds ' + j.month,
    body: (j.lockReason || 'the month lock is held') + '\n\nThis run did nothing. Wait for the other run, or clear the lock:\n' +
      '  npm run pipeline -- --stage lock --month ' + j.month + ' --status',
    releaseLock: false,
  },
}];

/* §3.4 step 6: one or more cohorts did not collect, so the month is INCOMPLETE
   and stages 05-07 must not run on it. Building a report where a cohort's calls
   never arrived produces books whose AI figures are silently short — accounts,
   outstanding and recovered all still render correctly, and only the thing the
   client is paying to see is wrong.

   AMBER, not red. Each individual cohort failure was already escalated by the
   Cohort Loop with its own severity (a crash red, a question amber). This
   message is the pipeline REFUSING TO BUILD, which is it working. */
const r = $('Resolve month').first().json;
const s = $input.first().json;

const body = [
  s.reason,
  '',
  ...(s.failed || []).map((f) => '  ' + f.key + ' — ' + f.outcome + ' after ' + f.attempts + ' attempt(s): ' + String(f.reason).slice(0, 200)),
  '',
  'Collected ' + s.collected + ' of ' + s.attempted + ' attempted (' + s.alreadyCollected + ' were already done).',
  '',
  'Stages 05-07 have been skipped deliberately. Resolve the cohorts above and run',
  'the workflow again — everything already collected is skipped on the re-run.',
].join('\n');

return [{
  json: {
    ...r,
    severity: 'stop',
    stage: '03/04',
    title: 'month incomplete — ' + (s.failed || []).length + ' cohort(s) unresolved',
    body,
    releaseLock: true,
  },
}];

/* One stage did not finish. Decide what kind of event that is — and the
   distinction is the whole point of the exit-code contract:

     outcome "stop"  → exit 10 → the pipeline REFUSED TO GUESS. Amber. Not a
                       failure, and nothing before it has to be repeated.
     outcome "crash" → anything else → red.

   Nothing here decides what the data means; it reads the envelope the Stage
   Runner already classified and routes on it. */

const env = $input.first().json;
const r = $('Resolve month').first().json;

const isStop = env.outcome === 'stop';
const stageJson = env.json ?? {};
const reason = stageJson.reason || env.contractViolation || env.stderrTail || 'no reason reported';

const body = [
  (isStop ? 'Stopped at' : 'Crashed at') + ' stage ' + env.stage + ' (' + (env.label || '') + ') after ' + Math.round((env.durationMs || 0) / 1000) + 's.',
  '',
  reason,
  '',
  isStop
    ? 'Nothing before this stage has to be repeated — every stage is idempotent and\nconsults state/' + r.month + '.json. Resolve the question and run the workflow again.'
    : 'Re-running is safe: completed work will not repeat.',
  env.contractViolation ? '\nCONTRACT VIOLATION: ' + env.contractViolation : '',
].filter(Boolean).join('\n');

return [{
  json: {
    ...r,
    severity: isStop ? 'stop' : 'fail',
    stage: env.stage,
    title: (isStop ? 'awaiting a decision at stage ' : 'stage ') + env.stage + (isStop ? '' : ' failed'),
    body,
    outcome: env.outcome,
    exitCode: env.exitCode,
    releaseLock: true,
  },
}];

/* Build the quoted lock command. Same discipline as the Stage Runner: the
   only place a value reaches a shell is a Code node that quotes every token. */
const inp = $input.first().json ?? {};
const r = $('Resolve month').first().json;
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
const repo = $vars.RBL_REPO;
if (!repo) throw new Error('n8n variable RBL_REPO is not set — see n8n/SETUP_MONTH_PIPELINE.md');

const command = 'cd ' + q(repo)
  + ' && npm run pipeline --silent -- --stage lock --month ' + q(r.month)
  + ' --release --run-id ' + q(r.runId)
  + ' --json';

/* Spread the INCOMING item, not just Resolve month: on the release path this
   carries the severity, title and body that Notify is about to send. */
return [{ json: { ...inp, month: r.month, runId: r.runId, dryRun: r.dryRun, startedAt: r.startedAt, command } }];

/* Did the lock come off? A held lock wedges the next scheduled run, and the
   failure surfaces a month later pointing at a process that died in October. */
const prev = $('Build the release command').first().json;
const out = $('Release the lock').first().json;

/* THE SENTINEL IS THE ONLY RELIABLE EXIT CODE. Measured on n8n 2.35.7: the
   Execute Command node reports `exitCode` only when the command exits 0. On any
   non-zero exit it emits `{ error }` alone — no exitCode, no stdout — so a
   lock.mjs exit 10 ("someone else holds this month", a decision) is
   indistinguishable from a crash. The command is wrapped to always exit 0 and
   print __EXIT__<code> on stdout. */
const stdoutRaw = String(out.stdout ?? '');
const sentinelMatch = [...stdoutRaw.matchAll(/^__EXIT__(\d+)\s*$/gm)].pop();
const exitCode = sentinelMatch ? Number(sentinelMatch[1])
  : (Number.isFinite(Number(out.exitCode)) ? Number(out.exitCode) : (out.error ? 1 : 0));
const stdout = stdoutRaw.replace(/^__EXIT__\d+\s*$/gm, '');
const line = stdout.split('\n').map((l) => l.trim()).filter((l) => l.startsWith('{')).pop();
let res = null;
try { res = line ? JSON.parse(line) : null; } catch (e) { res = null; }

const released = res?.released === true || (res?.released === false && /no lock was held/i.test(res?.reason ?? ''));

return [{
  json: {
    ...prev,
    body: prev.body + (released ? '' : '\n\nMONTH LOCK NOT RELEASED — ' + (res?.reason ?? 'no parseable result') +
      '\nClear it with: npm run pipeline -- --stage lock --month ' + prev.month + ' --status'),
    lockReleased: released,
  },
}];

/* Build the command that records the answer and re-runs the stage.

   THE REPO IS THE AUDIT RECORD, NOT N8N (§3.3). n8n's execution data is pruned,
   is not diffable, and is not where anyone looks in six months.
   --apply-assignments writes state/campaigns.json and --apply-rulings writes
   state/<month>.json, both with decidedBy and decidedAt, and both re-run their
   stage in the same invocation so the operator sees the result their answer
   produced. */

const ask = $('Build the question').first().json;
const form = $input.first().json;

const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
const repo = $vars.RBL_REPO;
if (!repo) throw new Error('n8n variable RBL_REPO is not set — see n8n/SETUP_MONTH_PIPELINE.md');

/* The form returns the edited JSON as a string. Parse it here so a malformed
   answer fails with a clear message rather than reaching a shell. */
const raw = form['Your answers'] ?? form.answers ?? '';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('the submitted answer is not valid JSON (' + e.message + '). Nothing was applied; re-run the workflow to be asked again.');
}
if (!Array.isArray(parsed) || !parsed.length) throw new Error('the submitted answer must be a non-empty JSON array.');

const decidedBy = String(form['Your name'] ?? '').trim() || 'n8n-form';
const flag = ask.stage === '02' ? '--apply-assignments' : '--apply-rulings';

const command = 'cd ' + q(repo)
  + ' && npm run pipeline --silent -- --stage ' + q(ask.stage)
  + ' --month ' + q(ask.month)
  + ' ' + flag + ' ' + q(JSON.stringify(parsed))
  + ' --decided-by ' + q(decidedBy)
  + ' --run-id ' + q(ask.runId)
  + ' --json';

return [{ json: { ...ask, decidedBy, answerCount: parsed.length, command } }];

/* Did the answer stick? A rejected form (unknown book name, missing reason) is
   an operator error, not a new decision point — it comes back RED so it cannot
   be mistaken for the pipeline asking the same question again. */
const meta = $('Build the apply command').first().json;
const out = $('Record the decision').first().json;

/* THE SENTINEL IS THE ONLY RELIABLE EXIT CODE. Measured on n8n 2.35.7: the
   Execute Command node reports `exitCode` only when the command exits 0. On any
   non-zero exit it emits `{ error }` alone — no exitCode, no stdout — so a
   lock.mjs exit 10 ("someone else holds this month", a decision) is
   indistinguishable from a crash. The command is wrapped to always exit 0 and
   print __EXIT__<code> on stdout. */
const stdoutRaw = String(out.stdout ?? '');
const sentinelMatch = [...stdoutRaw.matchAll(/^__EXIT__(\d+)\s*$/gm)].pop();
const exitCode = sentinelMatch ? Number(sentinelMatch[1])
  : (Number.isFinite(Number(out.exitCode)) ? Number(out.exitCode) : (out.error ? 1 : 0));
const stdout = stdoutRaw.replace(/^__EXIT__\d+\s*$/gm, '');
const line = stdout.split('\n').map((l) => l.trim()).filter((l) => l.startsWith('{')).pop();
let res = null;
try { res = line ? JSON.parse(line) : null; } catch (e) { res = null; }

const accepted = exitCode === 0 && res?.ok === true;
const rejected = res?.rejected ?? [];

return [{
  json: {
    ...meta,
    accepted,
    exitCode,
    result: res,
    severity: accepted ? 'info' : 'fail',
    title: accepted ? 'decision applied — stage ' + meta.stage + ' re-ran' : 'decision REJECTED at stage ' + meta.stage,
    body: accepted
      ? meta.answerCount + ' answer(s) recorded by ' + meta.decidedBy + ' and stage ' + meta.stage + ' re-ran successfully.\n\n' +
        (res?.reason ?? '') + '\n\nThe decision is in the repo (state/), not in n8n.'
      : 'The submitted answers were refused and NOTHING was written:\n\n' +
        rejected.map((x) => '  ' + (x.book ?? JSON.stringify(x.entry)) + ' — ' + x.why).join('\n') +
        '\n\n' + (res?.reason ?? ('exit ' + exitCode)) +
        '\n\nRe-run the workflow to be asked again.',
    releaseLock: true,
  },
}];

/* Nobody answered. An execution waiting forever is how a queue silently fills,
   so the wait has a deadline — and the deadline releases the lock, because a
   month held by an unanswered question blocks every later run of it. */
const ask = $('Build the question').first().json;
return [{
  json: {
    ...ask,
    severity: 'stop',
    title: 'no answer after 48h — ' + ask.month + ' released',
    body: ask.formHeading + '\n\nNobody answered within 48 hours, so the run ended and the month lock was\n' +
      'released. Nothing was decided and nothing was built. Re-run the workflow when\n' +
      'someone can answer — every stage before this one is idempotent and will be skipped.',
    releaseLock: true,
  },
}];

/* The month is verified and the client documents exist. This is the only
   notification that carries files.

   The per-book PDFs are NOT uploaded anywhere yet: S3_PREFIX_OUTPUT is not
   configured and stage 01's S3 path has never run against a real bucket, so an
   upload here would be a second unproven network leg on the one path that
   reaches the client. Their locations are listed instead, and the operator
   sends them the way they always have. */
const r = $('Resolve month').first().json;
const client = $input.first().json;
const j = client.json ?? {};
const docs = j.documents ?? [];

const built = $('06 · Build the PDFs').first().json.json ?? {};
const perBook = built.reports ?? [];

const attachments = docs.map((d) => d.pdf).filter(Boolean).join(',');

const body = [
  'The ' + r.month + ' run is complete and verified.',
  '',
  ...docs.map((d) => '  ' + d.label + ' Portfolio — ' + d.books + ' book(s), ' +
    Number(d.accounts).toLocaleString('en-IN') + ' accounts, ' +
    Number(d.attempts).toLocaleString('en-IN') + ' AI attempts'),
  '',
  docs.length ? 'Client portfolios attached.' : 'No client portfolios were produced.',
  '',
  perBook.length + ' per-book report(s) are in:',
  '  ' + (built.outDir ?? '(unknown)'),
  '',
  'They are not uploaded anywhere — S3_PREFIX_OUTPUT is not configured, and the',
  'S3 path has never run against a real bucket. Send them as you always have.',
  '',
  r.dryRun ? 'THIS WAS A DRY RUN — the documents are in a temp directory and nothing was delivered.' : '',
].filter(Boolean).join('\n');

return [{
  json: {
    ...r,
    severity: 'info',
    stage: '08',
    title: r.dryRun ? 'dry run complete' : 'month complete — portfolios attached',
    body,
    attachments: r.dryRun ? '' : attachments,
    documents: docs,
    releaseLock: true,
  },
}];
